// Run on a server. Never ship the key to a browser.
const response = await fetch(`${process.env.TSELA_API_URL}/v1/routes?limit=25`, {
  headers: { "X-API-Key": process.env.TSELA_API_KEY },
  signal: AbortSignal.timeout(10_000),
});
if (!response.ok) {
  throw new Error(`Tsela ${response.status} (request ${response.headers.get("x-request-id")})`);
}
const routes = await response.json();

// Run on a server. Never ship the key to a browser.
const response = await fetch(`${process.env.TSELA_API_URL}/v1/routes/3/geometry`, {
  headers: { "X-API-Key": process.env.TSELA_API_KEY },
  signal: AbortSignal.timeout(20_000),
});
if (response.status === 404) return null;
if (!response.ok) {
  throw new Error(`Tsela ${response.status} (request ${response.headers.get("x-request-id")})`);
}
const geometry = await response.json();
if (!geometry.isRoadAligned) console.warn(geometry.warning);
